public static class Worker
{
    public static Task<int> ProcessAsync<T>(IEnumerable<T> items, Func<T, CancellationToken, Task> work, int maxConcurrency, CancellationToken cancellationToken = default)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(maxConcurrency, 1);
        return Run();

        async Task<int> Run()
        {
            using var gate = new SemaphoreSlim(maxConcurrency);
            var errors = new System.Collections.Concurrent.ConcurrentQueue<Exception>();
            int done = 0;
            var running = new List<Task>();
            foreach (var item in items)
            {
                await gate.WaitAsync(cancellationToken);
                running.Add(Task.Run(async () =>
                {
                    try
                    {
                        await work(item, cancellationToken);
                        Interlocked.Increment(ref done);
                    }
                    catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested) { }
                    catch (Exception e) { errors.Enqueue(e); }
                    finally { gate.Release(); }
                }));
            }
            await Task.WhenAll(running);
            cancellationToken.ThrowIfCancellationRequested();
            if (!errors.IsEmpty) throw new AggregateException(errors);
            return done;
        }
    }

    public static long CountPrimes(int limit)
    {
        long count = 0;
        Parallel.For(2, Math.Max(2, limit), () => 0L, (n, _, local) =>
        {
            for (int d = 2; (long)d * d <= n; d++) if (n % d == 0) return local;
            return local + 1;
        }, local => Interlocked.Add(ref count, local));
        return count;
    }
}

