static T Run<T>(Task<T> task) => task.GetAwaiter().GetResult();

Test("respects the limit", () =>
{
    int running = 0, peak = 0;
    object gate = new();
    async Task Job(int n, CancellationToken ct)
    {
        lock (gate) { running++; peak = Math.Max(peak, running); }
        await Task.Delay(20, ct);
        lock (gate) running--;
    }
    CheckEq(Run(Worker.ProcessAsync(Enumerable.Range(1, 10), Job, 3)), 10);
    CheckEq(peak, 3);
    CheckEq(Run(Worker.ProcessAsync(new int[0], Job, 2)), 0);
    CheckThrows<ArgumentOutOfRangeException>(() => Worker.ProcessAsync(new[] { 1 }, Job, 0));
});

Test("collects failures and keeps going", () =>
{
    int done = 0;
    async Task Job(int n, CancellationToken ct)
    {
        await Task.Delay(5, ct);
        if (n % 3 == 0) throw new InvalidOperationException($"item {n}");
        Interlocked.Increment(ref done);
    }
    try
    {
        Run(Worker.ProcessAsync(Enumerable.Range(1, 9), Job, 2));
        Check(false, "should throw");
    }
    catch (AggregateException e)
    {
        CheckEq(e.InnerExceptions.Select(x => x.Message).Order(), new[] { "item 3", "item 6", "item 9" });
    }
    CheckEq(done, 6);
});

Test("cancellation stops the work", () =>
{
    int started = 0;
    async Task Job(int n, CancellationToken ct)
    {
        Interlocked.Increment(ref started);
        await Task.Delay(100, ct);
    }
    using var cts = new CancellationTokenSource(TimeSpan.FromMilliseconds(150));
    var sw = System.Diagnostics.Stopwatch.StartNew();
    CheckThrows<OperationCanceledException>(() => Run(Worker.ProcessAsync(Enumerable.Range(1, 100), Job, 2, cts.Token)));
    Check(started < 10, $"started {started} jobs: new items should stop after cancelling");
    Check(sw.ElapsedMilliseconds < 1000, "running work should stop early");
});

Test("counting primes in parallel", () =>
{
    CheckEq(Worker.CountPrimes(10), 4L);
    CheckEq(Worker.CountPrimes(2), 0L);
    CheckEq(Worker.CountPrimes(100_000), 9592L);
});

